import json,subprocess
BG="[0:v]split=%d[b0]%s;[b0]crop=ih*9/16:ih,scale=1080:1920,gblur=sigma=40,eq=brightness=-0.25[bg]"
def comp(src,out,parts):
    n=len(parts)+1
    f=BG%(n,"".join(f"[s{i}]" for i in range(len(parts))))
    last="bg"
    for i,(crop,w,y) in enumerate(parts):
        f+=f";[s{i}]crop={crop},scale={w}:-2[p{i}];[{last}][p{i}]overlay=(W-w)/2:{y}[o{i}]"; last=f"o{i}"
    subprocess.run(["ffmpeg","-v","error","-y","-i",src,"-filter_complex",f,"-map",f"[{last}]","-map","0:a","-c:v","libx264","-preset","veryfast","-crf","18","-c:a","copy",out],check=True)
comp("hugo.mp4","c_hugo.mp4",[("1200:940:360:0",1080,430)])
comp("etoiles.mp4","c_et.mp4",[("880:666:370:234",1080,450)])
comp("zera.mp4","c_zera.mp4",[("1500:600:0:0",1080,370),("510:285:1374:759",1080,810)])

