def spec(tag,src,end,guest,cat,hook,ctx,caps,zooms,take,es):
    s=dict(src=f"/home/claude/w/{src}",start=0,end=end,guest=guest,category=cat,hook=hook,context=ctx,source=f"{guest} · Twitch",captions=caps,zooms=zooms,takeaway=take,end_secs=es)
    json.dump(s,open(tag+".json","w"),ensure_ascii=False,indent=1)
